<?php
namespace Tests\Feature;
use App\Models\{Club,ClubMembership,Member,ProfileUpdateRequest,ProfileUpdateRequestChange,Role,User};use Database\Seeders\DatabaseSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Schema;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class Milestone3haProfileUpdateRequestDatabaseReadFoundationTest extends TestCase{use RefreshDatabase;
 private const BASE='c2c79d64aef423fbfecb5b7755d6cb6e9d6d9d71';private const SUBJECT='Add profile update request read foundation';
 public function test_schema_permissions_and_read_routes_only():void{$this->seed(DatabaseSeeder::class);foreach(['profile_update_requests','profile_update_request_changes'] as $t)$this->assertTrue(Schema::hasTable($t));foreach(['president-admin','secretary'] as $role){$p=Role::where('slug',$role)->firstOrFail()->permissions->pluck('slug');foreach(['profile_updates.self.submit','profile_updates.self.view','profile_updates.review','profile_updates.approve'] as $x)$this->assertTrue($p->contains($x));}foreach(['treasurer','member'] as $role){$p=Role::where('slug',$role)->firstOrFail()->permissions->pluck('slug');$this->assertTrue($p->contains('profile_updates.self.view'));$this->assertFalse($p->contains('profile_updates.review'));}$routes=collect(app('router')->getRoutes())->map(fn($r)=>[$r->methods(),$r->uri()]);$profile=$routes->filter(fn($r)=>str_contains($r[1],'profile-update-requests'));$mutationsActive=class_exists(\App\Services\ProfileUpdates\ProfileUpdateWriteService::class);$this->assertCount($mutationsActive?8:4,$profile);if(!$mutationsActive)$this->assertTrue($profile->every(fn($r)=>$r[0]===['GET','HEAD']));}
 public function test_own_history_queue_privacy_filters_pagination_and_scope():void{$this->seed(DatabaseSeeder::class);$c=$this->club('A');$other=$this->club('B');[$memberUser,$member]=$this->actorMember($c,'member','DUP','Duplicate Person');[, $duplicate]=$this->actorMember($c,'member','DUP2','Duplicate Person');[$president]=$this->actorMember($c,'president-admin','P','President');$request=$this->request($c,$member,$memberUser,'pending','phone','999','888');$this->request($c,$duplicate,$duplicate->user,'approved','occupation','Old','New');$cross=$this->actorMember($other,'member','X','CROSS-SENTINEL')[1];$this->request($other,$cross,$cross->user,'pending','phone','1','2');Sanctum::actingAs($memberUser);config(['instance.organisation_code' => $c->code]); $own=$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests/me?status=pending&per_page=1")->assertOk()->assertJsonPath('meta.total',1)->assertJsonPath('data.0.id',$request->id);$this->assertArrayNotHasKey('changes',$own->json('data.0'));$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests/me/{$request->id}")->assertOk()->assertJsonPath('data.changes.0.proposed_value','888');$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests/me/999999")->assertNotFound();Sanctum::actingAs($president);$q=$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests?member_search=Duplicate&changed_field=phone&per_page=1")->assertOk()->assertJsonPath('meta.total',1)->assertJsonPath('data.0.id',$request->id);$serialized=json_encode($q->json());$this->assertStringNotContainsString('888',$serialized);$this->assertStringNotContainsString('CROSS-SENTINEL',$serialized);$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests?unknown=x")->assertUnprocessable();}
 public function test_denials_empty_state_constraints_and_no_mutations():void{$this->seed(DatabaseSeeder::class);$c=$this->club('C');[$memberUser,$m]=$this->actorMember($c,'member','M','Member');Sanctum::actingAs($memberUser);config(['instance.organisation_code' => $c->code]); $this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests/me")->assertOk()->assertJsonPath('data',[])->assertJsonPath('meta.total',0);$this->getJson("/api/v1/clubs/{$c->id}/profile-update-requests")->assertForbidden();if(!class_exists(\App\Services\ProfileUpdates\ProfileUpdateWriteService::class))$this->postJson("/api/v1/clubs/{$c->id}/profile-update-requests",['changes'=>['phone'=>'1']])->assertMethodNotAllowed();$r=$this->request($c,$m,$memberUser,'pending','phone','1','2');$this->expectException(\Illuminate\Database\QueryException::class);ProfileUpdateRequest::create(['club_id'=>$c->id,'member_id'=>$m->id,'requester_user_id'=>$memberUser->id,'status'=>'pending','pending_guard'=>1,'source_fingerprint'=>str_repeat('b',64),'submitted_at'=>now(),'lock_version'=>1]);}

 public function test_changed_file_scope_is_lifecycle_safe():void{$root=dirname(__DIR__,3);$matches=[];exec('git -C "'.$root.'" log --all --format=%H%x09%s',$lines,$code);$this->assertSame(0,$code);foreach($lines as $line){[$hash,$subject]=array_pad(explode("	",$line,2),2,'');if($subject===self::SUBJECT)$matches[]=$hash;}$this->assertLessThanOrEqual(1,count($matches));if($matches){exec('git -C "'.$root.'" diff-tree --no-commit-id --name-only -r '.$matches[0],$files,$status);$this->assertSame(0,$status);}else{$this->assertSame(self::BASE,trim(shell_exec('git -C "'.$root.'" rev-parse HEAD')));exec('git -C "'.$root.'" status --porcelain=v1 -uall',$raw,$status);$this->assertSame(0,$status);$files=array_map(fn($x)=>str_replace('\\','/',substr($x,3)),$raw);}$allowed=['backend/app/Http/Controllers/Api/V1/ProfileUpdates/ProfileUpdateRequestController.php','backend/app/Http/Requests/ProfileUpdates/ListProfileUpdateRequestsRequest.php','backend/app/Models/ProfileUpdateRequest.php','backend/app/Models/ProfileUpdateRequestChange.php','backend/app/Services/ProfileUpdates/ProfileUpdateReadService.php','backend/database/migrations/2026_06_25_100001_create_profile_update_request_tables.php','backend/database/seeders/DefaultRolesAndPermissionsSeeder.php','backend/docs/milestone_3ha_profile_update_request_database_read_foundation.md','backend/routes/api.php','backend/tests/Feature/ClubPermissionServiceTest.php','backend/tests/Feature/DefaultRolesAndPermissionsSeederTest.php','backend/tests/Feature/Milestone3haProfileUpdateRequestDatabaseReadFoundationTest.php'];sort($files);sort($allowed);$this->assertSame($allowed,$files);}
 private function club($x):Club{return Club::create(['name'=>$x,'code'=>$x.uniqid(),'timezone'=>'Asia/Kolkata','is_active'=>true]);}private function actorMember($c,$role,$code,$name):array{$u=User::factory()->create();ClubMembership::create(['club_id'=>$c->id,'user_id'=>$u->id,'role_id'=>Role::where('slug',$role)->firstOrFail()->id,'status'=>'active','joined_at'=>now()]);$m=Member::create(['club_id'=>$c->id,'user_id'=>$u->id,'member_code'=>$code,'full_name'=>$name,'status'=>'active']);return[$u,$m];}private function request($c,$m,$u,$status,$field,$old,$new):ProfileUpdateRequest{$r=ProfileUpdateRequest::create(['club_id'=>$c->id,'member_id'=>$m->id,'requester_user_id'=>$u->id,'status'=>$status,'pending_guard'=>$status==='pending'?1:null,'source_member_updated_at'=>$m->updated_at,'source_fingerprint'=>hash('sha256',$m->updated_at.$field),'submitted_at'=>now(),'decided_at'=>$status==='pending'?null:now(),'lock_version'=>1]);ProfileUpdateRequestChange::create(['profile_update_request_id'=>$r->id,'field_key'=>$field,'classification'=>'restricted','original_value'=>$old,'proposed_value'=>$new]);return$r;}}
